import React, { useEffect, useRef } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import dynamic from 'next/dynamic';
import styled from 'styled-components';
import ReactLoader from 'components/common/reactLoading';
import { setActiveTab } from 'redux/actions/sessionStatistics';
import SessionLockedModal from 'components/features/sessions/SessionDetailsAndVideo/SessionLockedModal'
import { useFeatureFlag } from 'uxcam-frontend-components';
import Router from 'next/router';
import useSidebarUtils from 'components/IntegratePages/layout/dashboardMenu/Sidebar/hooks/useSidebarUtils';
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext';
import useSessionAnalyticsAPI from '../SessionStatistics/hooks/useSessionAnalyticsAPI';
import SessionDetailsAndVideo from '../SessionDetailsAndVideo'

const SessionStatisticsWrapper = styled.div`
  padding: 12px 16px 0;
`;

const SessionStatistics = dynamic(import('../SessionStatistics'), {
  loading: () => <ReactLoader />,
});

const OverviewBoxes = dynamic(import('components/common/Analytics/OverviewBoxes'), { loading: () => <ReactLoader />}
);

const SessionList = () => {
  const dispatch = useDispatch();
  const { callStatsBoxes } = useSessionAnalyticsAPI();
  const { aiSessionFeatureAllowed: isAISession } = useRestrictionContext() || {};
  const isAISessionRef = useRef( isAISession )
  const {
    urlReducer: { appId, parentType, sessionid, starttime },
  } = useSelector((state) => state);
  const { getRouteUrl } = useSidebarUtils()
  

  useEffect(() => {
    dispatch(setActiveTab(parentType));
  }, [dispatch, parentType]);

  useEffect(() => {
    if (appId) callStatsBoxes();
  }, [appId]);

  isAISessionRef.current = isAISession
  
  useEffect( () => {
      const timeout = setTimeout( () => {
        if ( isAISessionRef.current ) {
          // If there's a sessionid, route to AI session detail page
          if ( sessionid ) {
            const timestampUrl = starttime ? `/${starttime}` : '';
            const routeQuery = `/integration?parentType=aiSessionsList&appId=${appId}&sessionpage=1&starttime=${starttime || 0}&sessionid=${sessionid}&secondarysessionid=${sessionid}`
            const routeUrl = `/app/${appId}/aisessions/list/1/${sessionid}${timestampUrl}?secondarysessionid=${sessionid}`;
            Router.push(routeQuery, routeUrl);
          } else {
            // Otherwise route to AI sessions list page
            const routeQuery = `/integration?appId=${appId}&parentType=aiSessionsList`
            const routeUrl = getRouteUrl('aiSessionsList');
            Router.push(routeQuery, routeUrl);
          }
        }
      }, 1000 )
      return () => clearTimeout( timeout )
  }, [ dispatch, appId, sessionid, starttime, getRouteUrl ] )

  if (['sessionStatistics', 'sessionsList'].includes(parentType)) {
    if (parentType === 'sessionStatistics')
      return (
        <>
          <OverviewBoxes />
          <SessionStatisticsWrapper>
            <SessionStatistics
              isNewSession
            />
          </SessionStatisticsWrapper>
        </>
      );
    return (
        <>
          <SessionLockedModal />
          <SessionDetailsAndVideo />
        </>
    );
  }
  return null;
};
export default SessionList;
