import React, { useEffect, useMemo } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Layout } from 'antd';
import styled from 'styled-components';
import SessionList from 'components/features/sessions/SessionBlock/SessionList';
import { fetchPlanHatApi } from 'redux/actions/common';
import useEventUserProperties from 'hooks/useEventUserProperties';

const { Content } = Layout;

const ContentContainer = styled.div`
  height: 100%;
  padding-top: 60px;
  pointer-events: ${( {isGlobalFilterVisible}) => isGlobalFilterVisible ?  `none` : ''};
`

const ContentWrapper = styled(Content)`
  min-height: 100%;
  padding: 0px;
`;
const NewSession = () => {
  const dispatch = useDispatch();
  const { megaDropdownVisible, megaBottomDropdownVisible } = useSelector(
    (state) => state.megaFilterReducer
  )

  const isGlobalFilterVisible = useMemo(() => megaDropdownVisible || megaBottomDropdownVisible, [megaDropdownVisible, megaBottomDropdownVisible])

  useEventUserProperties()

  useEffect(() => {
    dispatch(fetchPlanHatApi({ action: 'Entered session list page' }));
  }, []);

  return (
    <ContentContainer isGlobalFilterVisible={isGlobalFilterVisible}>
      <ContentWrapper>
        <SessionList />
      </ContentWrapper>
    </ContentContainer>
  );
};

export default NewSession;
